"""Typed run provenance and scene role tasks. Original jobs own execution state."""
from sqlalchemy import Table,Column,Text,Integer,DateTime,ForeignKey,ForeignKeyConstraint,PrimaryKeyConstraint,UniqueConstraint,CheckConstraint,Index,text
from sqlalchemy.dialects.postgresql import UUID,JSONB
CANVAS_EXECUTION_IMMUTABLE=('canvas_execution_steps','canvas_execution_models','spatial_plan_decisions','canvas_agent_action_results','intelligent_asset_runs')

def install_canvas_execution_schema(metadata):
    def uid(name,**kw):return Column(name,UUID(as_uuid=False),**kw)
    def stamp():return Column('created_at',DateTime(timezone=True),nullable=False,server_default=text('now()'))
    def table(name,*cols):return Table(name,metadata,uid('project_id',nullable=False),*cols,ForeignKeyConstraint(['project_id'],['projects.id']))
    def ref(local,target):return ForeignKeyConstraint(['project_id',local],[target+'.project_id',target+'.id'])
    steps=table('canvas_execution_steps',uid('id',nullable=False),uid('version_id',nullable=False),Column('node_key',Text,nullable=False),uid('shot_id'),uid('asset_id'),uid('spec_id'),uid('run_artifact_id',nullable=False),uid('source_step_id'),Column('model_count',Integer,nullable=False),Column('created_by',Text,nullable=False),stamp(),PrimaryKeyConstraint('project_id','id'),UniqueConstraint('project_id','source_step_id'),ForeignKeyConstraint(['project_id','version_id','node_key'],['creative_canvas_nodes.project_id','creative_canvas_nodes.version_id','creative_canvas_nodes.node_key']),ref('shot_id','shots'),ref('asset_id','asset_identities'),ref('spec_id','asset_spec_versions'),ref('run_artifact_id','artifact_versions'),ref('source_step_id','canvas_execution_steps'),CheckConstraint('(shot_id IS NULL)<>(asset_id IS NULL) AND (spec_id IS NULL OR asset_id IS NOT NULL) AND model_count BETWEEN 1 AND 8',name='shape'))
    models=table('canvas_execution_models',uid('step_id',nullable=False),Column('ordinal',Integer,nullable=False),Column('model_id',UUID(as_uuid=False),ForeignKey('provider_models.id'),nullable=False),PrimaryKeyConstraint('project_id','step_id','ordinal'),UniqueConstraint('project_id','step_id','model_id'),ref('step_id','canvas_execution_steps'),CheckConstraint('ordinal BETWEEN 0 AND 7',name='ordinal'))
    plans=table('spatial_plan_tasks',uid('id',nullable=False),uid('version_id',nullable=False),uid('dispatch_id',nullable=False),Column('message',Text,nullable=False),Column('skill_sha256',Text,nullable=False),Column('apply_mode',Text,nullable=False,server_default=text("'review'")),Column('status',Text,nullable=False),Column('started_at',DateTime(timezone=True)),Column('host_result',JSONB),Column('error',Text),uid('plan_artifact_id'),uid('output_version_id'),Column('created_by',Text,nullable=False),stamp(),PrimaryKeyConstraint('project_id','id'),ref('version_id','spatial_scene_versions'),ref('dispatch_id','role_dispatches'),ref('plan_artifact_id','artifact_versions'),ref('output_version_id','spatial_scene_versions'),CheckConstraint("status IN ('queued','running','result_ready','needs_input','planned','applied','rejected','stopped','failed','submission_unknown')",name='status'),CheckConstraint("apply_mode IN ('review','direct')",name='apply_mode'))
    decisions=table('spatial_plan_decisions',uid('id',nullable=False),uid('task_id',nullable=False),Column('outcome',Text,nullable=False),Column('reason',Text,nullable=False),Column('actor',Text,nullable=False),stamp(),PrimaryKeyConstraint('project_id','id'),UniqueConstraint('project_id','task_id'),ref('task_id','spatial_plan_tasks'),CheckConstraint("outcome IN ('confirm','reject','stop')",name='outcome'))
    actions=table('canvas_agent_action_results',uid('turn_id',nullable=False),Column('ordinal',Integer,nullable=False),uid('base_version_id',nullable=False),uid('output_version_id'),uid('run_artifact_id'),Column('actor',Text,nullable=False),stamp(),PrimaryKeyConstraint('project_id','turn_id','ordinal'),ref('turn_id','canvas_agent_turns'),ref('base_version_id','creative_canvas_versions'),ref('output_version_id','creative_canvas_versions'),ref('run_artifact_id','artifact_versions'),CheckConstraint('ordinal BETWEEN 0 AND 7',name='ordinal'))
    asset_runs=table('intelligent_asset_runs',uid('version_id',nullable=False),Column('asset_key',Text,nullable=False),uid('run_artifact_id',nullable=False),stamp(),PrimaryKeyConstraint('project_id','version_id','asset_key','run_artifact_id'),ForeignKeyConstraint(['project_id','version_id','asset_key'],['intelligent_assets.project_id','intelligent_assets.version_id','intelligent_assets.asset_key']),ref('run_artifact_id','artifact_versions'))
    tables=(steps,models,plans,decisions,actions,asset_runs)
    for t in tables:
        for c in t.c:
            if c.name.endswith('_id') and c.name not in {'project_id','id'}:Index('ix_'+t.name+'_'+c.name,t.c.project_id,c)
    return {t.name:t for t in tables}
